describe('File Download Functionality', () => {
  beforeEach(() => {
    cy.visit('/file-manager');
  });

  it('should successfully download a previously uploaded file', () => {
    // Upload a file first
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/sample.pdf', { force: true });
    cy.get('[data-testid="upload-button"]').click();
    cy.get('[data-testid="upload-success-message"]').should('be.visible').should('contain', 'File uploaded successfully');

    // Verify file appears in list
    cy.get('[data-testid="file-list"]').should('be.visible');
    cy.get('[data-testid="file-item"]').should('contain', 'sample.pdf');

    // Click download button for the file
    cy.get('[data-testid="file-item"]').within(() => {
      cy.get('[data-testid="download-button"]').click();
    });

    // Verify download prompt or file download starts
    cy.intercept('GET', '/api/files/download/sample.pdf').as('fileDownload');
    cy.wait('@fileDownload');

    // Verify download success message
    cy.get('[data-testid="download-success-message"]').should('be.visible').should('contain', 'File downloaded successfully');
    cy.get('[data-testid="download-success-message"]').should('contain', 'sample.pdf');
  });

  it('should handle download failure when file is not found', () => {
    // Attempt to download a non-existent file
    cy.get('[data-testid="file-list"]').should('be.visible');
    cy.get('[data-testid="file-item"]').should('not.exist');

    // Click download button on an empty state or non-existent file
    cy.get('[data-testid="download-button"]').click({ force: true });

    // Verify error message appears
    cy.get('[data-testid="download-error-message"]').should('be.visible');
    cy.get('[data-testid="download-error-message"]').should('contain', 'File not found');

    // Verify no success message appears
    cy.get('[data-testid="download-success-message"]').should('not.exist');

    // Verify download button is disabled or remains clickable for retry
    cy.get('[data-testid="download-button"]').should('be.visible');
  });
});
